/* ==========================================================================
   তারিখনামা · Dedicated Interactive Map Page Stylesheet
   Ancient Parchment Aesthetic, Leaflet Styling, and Responsive Design
   ========================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Anek+Bangla:wght@400;500;600;700&family=Noto+Serif+Bengali:wght@400;600;700&family=Tiro+Bangla:ital@0;1&display=swap');

:root {
  --ink: #2a2015;
  --ink-secondary: #5a4933;
  --muted: #826f54;
  --green: #1f4b36;
  --green-hover: #163727;
  --gold: #b0883b;
  --gold-2: #cfa858;
  --gold-light: #f5e7c4;
  --paper: #f8f1de;
  --paper-2: #fcf7ec;
  --paper-translucent: rgba(248, 241, 222, 0.94);
  --line: #d8c599;
  --line-light: #e7dac0;
  --card-bg: rgba(255, 251, 240, 0.92);
  --canvas-bg: #eae0c3;
  --map-filter: sepia(35%) brightness(96%) contrast(98%);
  --font-ui: 'Anek Bangla', system-ui, -apple-system, sans-serif;
  --font-serif: 'Noto Serif Bengali', Georgia, serif;
  --font-calligraphy: 'Li Alinur Nobin', 'Li Alinur Nobin Unicode', 'Alinur Nobin', 'AlinurNobin', 'Tiro Bangla', 'Noto Serif Bengali', serif;
}

[data-theme="dark"] {
  --ink: #ede6d8;
  --ink-secondary: #c9bea9;
  --muted: #9c907c;
  --green: #2d7353;
  --green-hover: #3aa677;
  --gold: #dfb86c;
  --gold-2: #f0cf85;
  --gold-light: #3a3220;
  --paper: #161b20;
  --paper-2: #1c2229;
  --paper-translucent: rgba(22, 27, 32, 0.95);
  --line: #3d3527;
  --line-light: #2d261b;
  --card-bg: rgba(28, 34, 41, 0.92);
  --canvas-bg: #0e1114;
  --map-filter: invert(100%) hue-rotate(180deg) brightness(90%) contrast(85%);
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  color: var(--ink);
  font: 15px/1.75 var(--font-ui);
  background: var(--canvas-bg) url('assets/geometric-pattern.svg') repeat;
  background-size: 118px;
  min-height: 100vh;
  transition: background-color 0.3s ease, color 0.3s ease;
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  background: radial-gradient(circle at 50% 0%, rgba(255, 248, 225, 0.18), transparent 45%),
              linear-gradient(var(--canvas-bg), var(--canvas-bg));
  opacity: 0.92;
  z-index: -1;
  pointer-events: none;
}

a {
  color: inherit;
  text-decoration: none;
}

button, input, select {
  font: inherit;
}

button {
  cursor: pointer;
}

/* Header */
.site-header {
  position: sticky;
  top: 0;
  z-index: 1000;
  height: 68px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 0 max(calc((100vw - 1280px) / 2), 4vw);
  background: var(--paper-translucent);
  border-bottom: 1px solid var(--line);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
}

.brand {
  display: flex;
  align-items: center;
  gap: 11px;
  font-weight: 700;
  color: var(--green);
  line-height: 1.15;
  white-space: nowrap;
}

[data-theme="dark"] .brand {
  color: var(--gold);
}

.brand-seal {
  display: grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border: 1px solid var(--gold);
  color: var(--gold);
  font-size: 22px;
  background: var(--paper-2);
  clip-path: polygon(28% 0, 72% 0, 100% 28%, 100% 72%, 72% 100%, 28% 100%, 0 72%, 0 28%);
}

.brand-text {
  display: flex;
  flex-direction: column;
}

.brand-title {
  font-size: 17px;
  font-weight: 700;
  font-family: var(--font-serif);
}

.brand small {
  margin-top: 2px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 500;
}

.main-nav {
  display: flex;
  align-items: center;
  gap: 4px;
}

.main-nav a {
  color: var(--ink-secondary);
  font-size: 13px;
  font-weight: 500;
  padding: 7px 12px;
  border-radius: 999px;
  white-space: nowrap;
  transition: all 0.2s ease;
}

.main-nav a:hover, .main-nav a.active {
  background: var(--gold-light);
  color: var(--ink);
}

.header-right {
  display: flex;
  align-items: center;
  gap: 10px;
}

.header-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 13px;
  font-size: 12px;
  font-weight: 600;
  border-radius: 999px;
  border: 1px solid var(--gold);
  background: var(--green);
  color: #fff6e0;
  transition: all 0.2s ease;
  white-space: nowrap;
}

.header-btn:hover {
  background: var(--green-hover);
  transform: translateY(-1px);
}

.theme-toggle-btn {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid var(--line);
  background: var(--paper-2);
  color: var(--gold);
  font-size: 16px;
  transition: all 0.2s ease;
  padding: 0;
}

/* Main Container & Centered Titles */
main {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px 60px;
}

.map-page-head {
  text-align: center;
  max-width: 820px;
  margin: 36px auto 28px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 10px;
  color: var(--gold);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.live-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--gold);
  box-shadow: 0 0 0 4px rgba(176, 136, 59, 0.22);
}

.map-page-head h1 {
  margin: 4px 0 10px;
  color: var(--green);
  font: 700 clamp(28px, 4vw, 42px) / 1.3 var(--font-calligraphy);
}

[data-theme="dark"] .map-page-head h1 {
  color: var(--gold);
}

.title-ornament {
  color: var(--gold);
  font-size: 16px;
  margin: 4px 0 10px;
  letter-spacing: 4px;
}

.map-page-lede {
  margin: 0;
  color: var(--ink-secondary);
  font-size: 15px;
  line-height: 1.9;
  text-align: center;
}

/* Controls Card */
.map-controls-card {
  border: 1.5px solid var(--gold);
  background: var(--card-bg);
  border-radius: 12px;
  padding: 18px 22px;
  margin-bottom: 24px;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.05);
}

.map-search-row {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 14px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line-light);
}

.map-search-box {
  flex: 1;
  min-width: 260px;
  display: flex;
  align-items: center;
  gap: 9px;
  min-height: 42px;
  padding: 0 14px;
  border: 1px solid var(--line);
  background: var(--paper-2);
  border-radius: 6px;
  color: var(--gold);
}

.map-search-box span {
  font-size: 20px;
}

.map-search-box input {
  flex: 1;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--ink);
  font-size: 13.5px;
}

.map-year-slider-box {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
}

.map-year-slider-box b {
  color: var(--green);
  font-size: 14px;
}

[data-theme="dark"] .map-year-slider-box b {
  color: var(--gold);
}

.map-year-slider-box input {
  width: 140px;
  accent-color: var(--gold);
}

.button.ghost.small-btn {
  padding: 8px 14px;
  font-size: 12px;
  border: 1px solid var(--line);
  background: var(--paper-2);
  color: var(--ink);
  border-radius: 6px;
}

.map-pills-group {
  margin-bottom: 10px;
}

.map-pills-group:last-child {
  margin-bottom: 0;
}

.pills-title {
  display: block;
  font-size: 11px;
  font-weight: 700;
  color: var(--muted);
  text-transform: uppercase;
  margin-bottom: 6px;
}

.pills-scroll-row {
  display: flex;
  align-items: center;
  gap: 6px;
  overflow-x: auto;
  padding-bottom: 4px;
  scrollbar-width: none;
  -webkit-overflow-scrolling: touch;
}

.pills-scroll-row::-webkit-scrollbar {
  display: none;
}

.filter-pill {
  border: 1px solid var(--line);
  background: var(--paper-2);
  color: var(--ink-secondary);
  padding: 5px 12px;
  font-size: 12px;
  border-radius: 999px;
  white-space: nowrap;
  cursor: pointer;
  transition: all 0.18s ease;
}

.filter-pill:hover {
  border-color: var(--gold);
  color: var(--ink);
}

.filter-pill.active {
  background: var(--green);
  border-color: var(--gold);
  color: #fff6e0;
  font-weight: 600;
}

[data-theme="dark"] .filter-pill.active {
  background: var(--green);
  color: #ffffff;
}

/* Map Shell */
.map-view-shell {
  position: relative;
  height: 580px;
  border: 2px solid var(--gold);
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.18);
  background: var(--canvas-bg);
}

.interactive-map {
  width: 100%;
  height: 100%;
  z-index: 1;
}

/* Parchment filter on map tiles */
.leaflet-tile-pane {
  filter: var(--map-filter);
}

/* Custom Marker Styling */
.custom-map-pin {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--green);
  border: 2px solid var(--gold-2);
  box-shadow: 0 0 10px rgba(176, 136, 59, 0.6);
  cursor: pointer;
  transition: transform 0.2s ease, background 0.2s ease;
}

.custom-map-pin:hover, .custom-map-pin.active {
  transform: scale(1.4);
  background: var(--gold);
  border-color: #ffffff;
  z-index: 1000 !important;
}

.leaflet-popup-content-wrapper {
  background: var(--paper-2);
  border: 1.5px solid var(--gold);
  border-radius: 8px;
  color: var(--ink);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.3);
  font-family: var(--font-ui);
}

.leaflet-popup-tip {
  background: var(--paper-2);
  border: 1px solid var(--gold);
}

.map-popup-card h3 {
  margin: 0 0 4px;
  font: 700 16px var(--font-serif);
  color: var(--green);
}

[data-theme="dark"] .map-popup-card h3 {
  color: var(--gold);
}

.map-popup-card small {
  display: block;
  color: var(--muted);
  font-size: 11px;
  margin-bottom: 8px;
}

.map-popup-card p {
  margin: 0 0 10px;
  font-size: 12px;
  line-height: 1.7;
  color: var(--ink-secondary);
}

.map-popup-events {
  margin-top: 8px;
  border-top: 1px solid var(--line);
  padding-top: 8px;
}

.map-popup-events h4 {
  margin: 0 0 6px;
  font-size: 11px;
  color: var(--gold);
  text-transform: uppercase;
}

.map-popup-event-link {
  display: block;
  font-size: 11px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  padding: 4px 8px;
  border-radius: 4px;
  margin-bottom: 4px;
  transition: background 0.16s ease;
}

.map-popup-event-link:hover {
  background: var(--gold-light);
  border-color: var(--gold);
}

.map-legend-overlay {
  position: absolute;
  bottom: 12px;
  left: 12px;
  z-index: 10;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 6px 14px;
  background: var(--paper-translucent);
  border: 1px solid var(--line);
  border-radius: 6px;
  font-size: 11px;
  color: var(--muted);
  backdrop-filter: blur(8px);
}

.legend-pin {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--green);
  border: 1.5px solid var(--gold);
  margin-right: 4px;
}

/* Places Drawer Grid Below Map */
.map-bottom-section {
  margin-top: 36px;
}

.map-bottom-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 18px;
  border-bottom: 1px solid var(--line);
  padding-bottom: 10px;
}

.map-bottom-head h2 {
  margin: 0;
  color: var(--green);
  font: 700 24px var(--font-serif);
}

[data-theme="dark"] .map-bottom-head h2 {
  color: var(--gold);
}

.map-bottom-head p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 12px;
}

.place-cards-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.place-card {
  border: 1px solid var(--line);
  background: var(--card-bg);
  padding: 14px;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s ease;
  text-align: left;
}

.place-card:hover, .place-card.active {
  border-color: var(--gold);
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.08);
  background: var(--paper-2);
}

.place-card b {
  display: block;
  font: 700 15px var(--font-serif);
  color: var(--green);
}

[data-theme="dark"] .place-card b {
  color: var(--gold);
}

.place-card small {
  display: block;
  color: var(--muted);
  font-size: 10.5px;
  margin: 2px 0 6px;
}

.place-card span {
  display: block;
  color: var(--ink-secondary);
  font-size: 11.5px;
  line-height: 1.6;
}

.place-card-events-count {
  display: inline-block;
  margin-top: 8px;
  font-size: 10px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 4px;
  background: var(--paper);
  border: 1px solid var(--line);
  color: var(--gold);
}

/* Footer */
footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-top: 1px solid var(--line);
  padding: 24px 0 32px;
  margin-top: 48px;
  color: var(--muted);
  font-size: 12px;
}

footer a {
  text-decoration: underline;
}

/* Detail dialog */
dialog {
  position: fixed;
  inset: 0;
  margin: auto;
  width: min(650px, calc(100vw - 28px));
  max-height: 86vh;
  overflow: auto;
  border: 1.5px solid var(--gold);
  background: var(--paper-2);
  color: var(--ink);
  padding: 28px;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.4);
  border-radius: 12px;
}

dialog::backdrop {
  background: rgba(10, 14, 18, 0.65);
  backdrop-filter: blur(5px);
}

.dialog-close {
  position: sticky;
  float: right;
  top: 0;
  width: 32px;
  height: 32px;
  border: 1px solid var(--line);
  background: var(--paper);
  color: var(--ink);
  font-size: 18px;
  border-radius: 50%;
  display: grid;
  place-items: center;
}

/* Fallback SVG Map */
.fallback-svg-map {
  width: 100%;
  height: 100%;
}

.fallback-svg-map .land {
  fill: #a9ae82;
  stroke: #e0d4b1;
  stroke-width: 1;
}

.fallback-svg-map .map-graticule {
  stroke: #f8efd9;
  stroke-opacity: 0.6;
}

/* Responsive */
@media (max-width: 900px) {
  .place-cards-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .map-view-shell {
    height: 480px;
  }
}

@media (max-width: 650px) {
  .site-header {
    height: 60px;
    padding: 0 14px;
  }
  .main-nav {
    display: none;
  }
  main {
    padding: 0 14px 40px;
  }
  .map-view-shell {
    height: 400px;
  }
  .place-cards-grid {
    grid-template-columns: 1fr;
  }
  .map-search-row {
    flex-direction: column;
    align-items: stretch;
  }
  .map-year-slider-box {
    justify-content: space-between;
  }
  footer {
    flex-direction: column;
    text-align: center;
    gap: 8px;
  }
}


/* ==========================================================================
   Atlas Split-View Workspace & Compact Drawer
   ========================================================================== */
.atlas-mobile-tabs {
  display: none;
  gap: 8px;
  margin-bottom: 12px;
}

.atlas-tab-btn {
  flex: 1;
  padding: 10px 14px;
  border-radius: 8px;
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--ink);
  font-family: inherit;
  font-size: 13.5px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}

.atlas-tab-btn.active {
  background: var(--gold-dark);
  color: #fff;
  border-color: var(--gold-dark);
}

.atlas-workspace {
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: 18px;
  height: 640px;
  margin-top: 14px;
  align-items: stretch;
}

.atlas-map-column {
  height: 100%;
  position: relative;
  min-height: 0;
}

.atlas-map-column .map-view-shell {
  height: 100%;
  margin-bottom: 0;
  box-shadow: 0 4px 20px rgba(0,0,0,0.08);
}

.atlas-places-drawer {
  display: flex;
  flex-direction: column;
  background: var(--surface);
  border: 2px solid var(--gold);
  border-radius: 12px;
  box-shadow: 0 4px 20px rgba(0,0,0,0.06);
  overflow: hidden;
  height: 100%;
  min-height: 0;
}

.drawer-header {
  padding: 14px 16px;
  border-bottom: 1px solid var(--border);
