/* ==========================================================================
   Mouse-Interactive Background & Smooth Section Dividers
   ========================================================================== */
body {
  background: var(--canvas-bg) url('assets/geometric-pattern.svg') repeat !important;
  background-size: 118px !important;
  background-position: calc(50% + var(--bg-shift-x, 0px)) calc(50% + var(--bg-shift-y, 0px)) !important;
  transition: background-color 0.3s ease, color 0.3s ease;
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  background: radial-gradient(circle 380px at var(--cursor-x, 50vw) var(--cursor-y, 30vh), rgba(223, 184, 108, 0.18) 0%, rgba(223, 184, 108, 0.05) 50%, transparent 80%),
              radial-gradient(circle at 50% 0%, rgba(255, 248, 225, 0.18), transparent 45%),
              linear-gradient(var(--canvas-bg), var(--canvas-bg)) !important;
  opacity: 0.94;
  z-index: -1;
  pointer-events: none;
  transition: background 0.12s ease-out;
}

[data-theme="dark"] body::before {
  background: radial-gradient(circle 420px at var(--cursor-x, 50vw) var(--cursor-y, 30vh), rgba(223, 184, 108, 0.18) 0%, rgba(223, 184, 108, 0.04) 50%, transparent 80%),
              radial-gradient(circle at 50% 0%, rgba(223, 184, 108, 0.08), transparent 50%),
              linear-gradient(var(--canvas-bg), var(--canvas-bg)) !important;
}

/* Smooth Gradient Section Divider (Eliminates uneven mdashes entirely) */
