  gap: 14px;
}

.feedback-form-group {
  display: flex;
  flex-direction: column;
  gap: 5px;
  text-align: left;
}

.feedback-form-group label {
  font-size: 12px;
  font-weight: 600;
  color: var(--ink);
}

.feedback-input {
  width: 100%;
  padding: 8px 12px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--paper);
  color: var(--ink);
  font-family: inherit;
  font-size: 13px;
  box-sizing: border-box;
}

.feedback-input:focus {
  outline: none;
  border-color: var(--gold);
  box-shadow: 0 0 0 3px rgba(176, 136, 59, 0.15);
}

.feedback-input.textarea {
  resize: vertical;
  min-height: 80px;
}

.feedback-modal-actions {
  display: flex;
  gap: 10px;
  margin-top: 6px;
  flex-wrap: wrap;
}

.feedback-submit-btn {
  flex: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: var(--green);
  color: #fff;
  border: 1px solid var(--gold);
  padding: 10px 16px;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}

.feedback-submit-btn:hover {
  background: var(--green-hover);
  transform: translateY(-1px);
}

.feedback-secondary-btn {
  background: var(--paper);
  border: 1px solid var(--line);
  color: var(--ink);
  padding: 10px 14px;
  border-radius: 6px;
  font-size: 12.5px;
  cursor: pointer;
}

.feedback-secondary-btn:hover {
  border-color: var(--gold);
}

.feedback-status {
  font-size: 12px;
  padding: 8px;
  border-radius: 4px;
  text-align: center;
}

/* Colophon Auxiliary Column & Select Classes */
.colophon-col {
  display: flex;
  flex-direction: column;
}
.colophon-identity {
  gap: 4px;
}
.colophon-curator {
  gap: 10px;
}
.colophon-actions {
  gap: 4px;
}
.quick-nav-label {
  display: block;
  font-weight: 700;
  color: var(--gold);
  margin-bottom: 4px;
}
select.select {
  cursor: pointer;
}
